from taf.ul.kpi_selector.operations.sw_activation.classical_sw_activation.sw_activation_22R1 import SwActivation22R1


class SwActivation22R2(SwActivation22R1):

    def get_kpi(self, inter_release=False):  # noqa: C901
        """
        Gets kpi for software activation operation.
        :param inter_release: boolean value whether activated sw is of different stream than the one active on BTS;
                              defaults to False
        :type inter_release: bool
        :return: dictionary with timeout, requirement and operation description for software activation
        :rtype: dict
        """
        use_restrictions = True

        if self.check_smod_bbmod_types(smod_type="ASIB", bbmod_types=["ABIL"]):
            if all(
                (
                    self.bts.number_of_bbmods <= 6,
                    self.bts.number_of_nr_cells <= 24,
                    self.bts.cell_technologies == "TDD",
                    self.bts.is_full_rack,
                    self.bts.setup_mode == "SA",
                    not self.bts.is_multi_rat,
                )
            ):
                self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.13966"
                if not self.bts.is_rmods_target_bd_sw_version_different and inter_release:
                    self.operation_details["Timeout"] += 720
                elif self.bts.is_rmods_target_bd_sw_version_different and inter_release:
                    self.operation_details["Timeout"] += 1008
                elif not self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                    self.operation_details["Timeout"] += 504
                elif self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                    self.operation_details["Timeout"] += 792

        elif self.check_smod_bbmod_types(smod_type="ASIB", bbmod_types=["ABIO"]):
            if all(
                (
                    self.bts.number_of_bbmods <= 1,
                    self.bts.number_of_rmods <= 6,
                    self.bts.number_of_nr_cells <= 6,
                    self.bts.cell_technologies == "TDD",
                    not self.bts.is_full_rack,
                    self.bts.setup_mode == "SA",
                    not self.bts.is_multi_rat,
                )
            ):
                self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.15748"
                if not self.bts.is_rmods_target_bd_sw_version_different and inter_release:
                    self.operation_details["Timeout"] += 576
                elif self.bts.is_rmods_target_bd_sw_version_different and inter_release:
                    self.operation_details["Timeout"] += 864
                elif not self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                    self.operation_details["Timeout"] += 360
                elif self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                    self.operation_details["Timeout"] += 648

        elif self.check_smod_bbmod_types(smod_type="ASIL", bbmod_types=["ABIN"]) \
                or self.check_smod_bbmod_types(smod_type="ASIB", bbmod_types=["ABIN"]):

            if all(
                (
                    self.bts.number_of_bbmods <= 1,
                    self.bts.number_of_rmods <= 1,
                    self.bts.number_of_nr_cells <= 6,
                    self.bts.cell_technologies == "FDD",
                    not self.bts.is_full_rack,
                    self.bts.setup_mode == "SA",
                    not self.bts.is_multi_rat,
                )
            ):
                self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.15702"
                if not self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                    self.operation_details["Timeout"] += 360
                elif self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                    self.operation_details["Timeout"] += 648

        elif self.check_smod_bbmod_types(smod_type="ASIL", bbmod_types=["ABIL"]):

            if all(
                (
                    self.bts.number_of_bbmods <= 1,
                    self.bts.number_of_nr_cells <= 3,
                    self.bts.cell_technologies == "TDD",
                    not self.bts.is_full_rack,
                    self.bts.setup_mode == "SA",
                    not self.bts.is_multi_rat,
                )
            ):
                self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.15444"
                if not self.bts.is_rmods_target_bd_sw_version_different and inter_release:
                    self.operation_details["Timeout"] += 576
                elif self.bts.is_rmods_target_bd_sw_version_different and inter_release:
                    self.operation_details["Timeout"] += 864
                elif not self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                    self.operation_details["Timeout"] += 360
                elif self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                    self.operation_details["Timeout"] += 648

            elif all(
                (
                    self.bts.number_of_bbmods <= 3,
                    self.bts.number_of_nr_cells <= 24,
                    self.bts.cell_technologies == "TDD",
                    not self.bts.is_full_rack,
                    not self.bts.is_multi_rat,
                )
            ):
                self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.15538"
                if not self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                    self.operation_details["Timeout"] += 864
                elif self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                    self.operation_details["Timeout"] += 1152

        elif "ASOD" in self.bts.smod_hw_types:
            if all(
                (
                    self.bts.number_of_nr_cells <= 8,
                    self.bts.cell_technologies == "TDD",
                    not self.bts.is_full_rack,
                    not self.bts.is_multi_rat,
                )
            ):
                self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.15539"
                if not self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                    self.operation_details["Timeout"] += 912
                elif self.bts.is_rmods_target_bd_sw_version_different and not inter_release:
                    self.operation_details["Timeout"] += 1200

        else:
            return super(SwActivation22R2, self).get_kpi(inter_release=inter_release)

        if use_restrictions:
            self.operation_details["Timeout"] += self.restrictions.use_restrictions_from_OM_GEN_SFS_PERF_CAP_13441()

        return self.operation_details
